        const b = boxOf(p, 0.95, cols, rows, { size: "medium", at: "bottom" });
        const bw = Math.max(3, Math.round(b.w * 0.72)), hw = b.w - bw;
        const bx0 = b.flip ? b.x0 + hw : b.x0, bx1 = bx0 + bw, y1 = b.y0 + b.h;
