/*
 * kit recipes, checks: the words every recipe takes in place of numbers, and
 * how they are checked, in one place so looks, motions and widgets read them
 * alike. A speed is "slow", "normal" or "fast" everywhere; an amount is
 * "subtle", "medium" or "strong"; a colour is #rrggbb, { light, dark } or a
 * palette's name. Not part of ascii.rest/kit's API: words.ts exports the types
 * and pieceOf() for recipes of your own.
 * Part of ascii.rest by @bas3line (https://github.com/bas3line), MIT licensed.
 */
import { chained, checkMeta, colorOf as inkOf, fail, suggest } from "../core.js";
import { ease as eases } from "../math.js";
/** The easing each plain word stands for. */
export const easings = Object.freeze({
    steady: "linear",
    smooth: "inOutSine",
    snappy: "outBack",
    springy: "outElastic",
    bouncy: "outBounce",
});
export const SPEEDS = { slow: 0.5, normal: 1, fast: 2 };
export const SCALES = { small: 0.6, medium: 1, large: 1.6, huge: 2.5 };
export const AMOUNTS = { subtle: 0.5, medium: 1, strong: 1.8 };
export const DENSITIES = { sparse: 0.45, normal: 1, dense: 2 };
export const HEADINGS = {
    left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1],
    "up-left": [-Math.SQRT1_2, -Math.SQRT1_2], "up-right": [Math.SQRT1_2, -Math.SQRT1_2],
    "down-left": [-Math.SQRT1_2, Math.SQRT1_2], "down-right": [Math.SQRT1_2, Math.SQRT1_2],
};
// --- checking what a recipe is given ----------------------------------------------------
/** A value as an error shows it: a string in quotes, a function by its name, anything else as it reads. */
export function show(v) {
    if (typeof v === "function")
        return v.name ? `${v.name}, a function: call it, ${v.name}()` : "a function";
    if (typeof v === "string")
        return JSON.stringify(v);
    if (Array.isArray(v))
        return `[${v.map(show).join(", ")}]`;
    if (v !== null && typeof v === "object") {
        try {
            return JSON.stringify(v) ?? String(v);
        }
        catch {
            return "an object";
        }
    }
    return String(v);
}
// Words as a sentence offers them: "a, b or c".
export const or = (words) => (words.length > 1 ? `${words.slice(0, -1).join(", ")} or ${words.at(-1)}` : (words[0] ?? ""));
// Words in quotes, as a sentence offers them.
const quoted = (words) => or(words.map((w) => JSON.stringify(w)));
// Words as a list: "a, b and c".
const and = (words) => (words.length > 1 ? `${words.slice(0, -1).join(", ")} and ${words.at(-1)}` : (words[0] ?? ""));
const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
/** An options object, checked for keys it does not take, so a typo throws instead of doing nothing. */
export function optionsOf(what, o, keys) {
    if (o === undefined)
        return {};
    if (!isObject(o))
        fail(`${what} takes its options as an object, such as { ${keys[0]}: ... }, not ${show(o)}`);
    for (const [k, v] of Object.entries(o))
        if (v !== undefined && !keys.includes(k))
            fail(`${what} has no option ${JSON.stringify(k)}${suggest(k, keys)}: it takes ${and(keys)}`);
    return o;
}
/** A number from lo to hi, or its default. */
export function numberOf(what, v, def, lo = -Infinity, hi = Infinity) {
    if (v === undefined)
        return def;
    if (typeof v !== "number" || !Number.isFinite(v) || v < lo || v > hi)
        fail(`${what} takes a number${hi === Infinity ? (lo === -Infinity ? "" : ` of ${lo} or more`) : ` from ${lo} to ${hi}`}, not ${show(v)}`);
    return v;
}
/** A whole number from lo to hi, or its default. */
export function wholeOf(what, v, def, lo, hi = Infinity) {
    if (v === undefined)
        return def;
    if (!Number.isInteger(v) || v < lo || v > hi)
        fail(`${what} takes a whole number ${hi === Infinity ? `of ${lo} or more` : `from ${lo} to ${hi}`}, not ${show(v)}`);
    return v;
}
/** One of a list of words, or its default. */
export function wordOf(what, v, words, def) {
    if (v === undefined)
        return def;
    if (!words.includes(v))
        fail(`${what} takes ${quoted(words)}, not ${show(v)}${suggest(v, words)}`);
    return v;
}
/**
 * Words to show, checked now rather than on the first frame: a string whose every character a cell can hold (no tab,
 * no emoji outside the Basic Multilingual Plane), on one line unless `lines`. Undefined when none is given.
 */
export function textOf(what, v, o = {}) {
    if (v === undefined)
        return undefined;
    if (typeof v !== "string")
        fail(`${what} takes words, not ${show(v)}`);
    const text = v.replace(/\r\n?/g, "\n");
    for (const ch of text) {
        if (ch === "\n" && o.lines)
            continue;
        const c = ch.charCodeAt(0);
        if (ch.length > 1 || c < 32 || (c >= 0x7f && c <= 0x9f) || (c >= 0xd800 && c <= 0xdfff))
            fail(`${what} takes words a cell can hold, one character each from the Basic Multilingual Plane${o.lines ? "" : " on one line"}: not ${JSON.stringify(ch)} in ${show(v.length > 40 ? v.slice(0, 40) + "..." : v)}`);
    }
    return text;
}
/** True or false, or its default. */
export function boolOf(what, v, def) {
    if (v === undefined)
        return def;
    if (typeof v !== "boolean")
        fail(`${what} takes true or false, not ${show(v)}`);
    return v;
}
/** A word that stands for a number, as `{ low: 1, high: 4 }` does for a height, or a number from lo to hi itself. */
export function sizeOf(what, v, words, def, lo = 0, hi = Infinity) {
    if (v === undefined)
        return typeof def === "number" ? def : words[def];
    if (typeof v === "string" && Object.hasOwn(words, v))
        return words[v];
    if (typeof v !== "number" || !Number.isFinite(v) || v < lo || v > hi)
        fail(`${what} takes ${quoted(Object.keys(words))}, or a number${hi === Infinity ? ` of ${lo} or more` : ` from ${lo} to ${hi}`}, not ${show(v)}${suggest(v, Object.keys(words))}`);
    return v;
}
/** A whole number used as a seed, 1 by default. */
export function seedOf(what, v) {
    if (v === undefined)
        return 1;
    if (!Number.isInteger(v))
        fail(`${what}'s seed takes a whole number, such as 7, not ${show(v)}`);
    return v;
}
// --- speed ------------------------------------------------------------------------------
/** A speed as times as fast as normal: 0.5 for "slow", 1 for "normal", 2 for "fast", or the number given. With `still`, "still" is 0. */
export function speedOf(what, v, o = {}) {
    if (o.still)
        return sizeOf(`${what}'s speed`, v, { still: 0, ...SPEEDS }, "normal", 0, 100);
    return sizeOf(`${what}'s speed`, v, SPEEDS, "normal", 0.01, 100);
}
/** The seconds one loop takes at a speed, from the recipe's `normal` seconds: `period` wins when given. */
export function secondsOf(what, o, normal) {
    // Rounded to hundredths, so loops of several motions come round together, as the kit's time rule counts them.
    if (o.period !== undefined)
        return Math.max(0.05, Math.round(numberOf(`${what}'s period`, o.period, normal, 0.05, 60) * 100) / 100);
    return Math.max(0.05, Math.round((normal / speedOf(what, o.speed)) * 100) / 100);
}
/**
 * The loops widgets keep to: every one divides a minute, so any widgets side by side, in a row(), a column() or a
 * dashboard grid(), come round together within one, and the dashboard loops.
 */
export const LOOPS = [0.25, 0.5, 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60];
/** Seconds as one of LOOPS: the nearest (by ratio), or with `up` the shortest at least as long. */
export function loopOf(seconds, up = false) {
    if (up)
        return LOOPS.find((l) => l >= seconds - 1e-9) ?? 60;
    let best = LOOPS[0];
    for (const l of LOOPS)
        if (Math.abs(Math.log(l / seconds)) < Math.abs(Math.log(best / seconds)))
            best = l;
    return best;
}
/** An easing by its name, as a function from 0..1 to 0..1. */
export function easeOf(what, v, def) {
    const name = v === undefined ? def : v;
    if (typeof name === "string" && Object.hasOwn(easings, name))
        return eases[easings[name]];
    if (typeof name === "string" && Object.hasOwn(eases, name))
        return eases[name];
    return fail(`${what} takes ${quoted(Object.keys(easings))}, or an easing's name from math such as "outCubic", not ${show(v)}`);
}
// --- colour -----------------------------------------------------------------------------
/**
 * One colour for each page from what a recipe's `color` takes: #rrggbb (the same on both), { light, dark }, or a
 * palette's name, which gives that palette's strong colour for each page: "ocean" is a deep blue on paper and a bright
 * one on a dark page. Undefined when none is given.
 */
export function colorOf(what, v) {
    return v === undefined ? undefined : inkOf(v, what);
}
// --- things -------------------------------------------------------------------------------
/** True for an area such as heart(), cup() or area.rect(). */
export const isArea = (v) => isObject(v) && v.kind === "area" && typeof v.place === "function";
/** True for a part made with shape() or emit(). */
export const isPart = (v) => isObject(v) && v.kind === "part" && typeof v.setup === "function";
/** True for a piece: meta and a default function. */
export const isPiece = (v) => isObject(v) && isObject(v.meta) && typeof v.default === "function";
/** True for a 3D shape made by torus(), sphere(), cube() and the rest: scene() says if it is not one after all. */
export const isShape3d = (v) => isObject(v) && typeof v.kind === "string" && v.kind !== "area" && v.kind !== "part" && v.kind !== "mask" && !("meta" in v) && !("src" in v);
/** True for a 3D shape or a list of them. */
export const is3d = (v) => isShape3d(v) || (Array.isArray(v) && v.length > 0 && v.every(isShape3d));
// --- naming -------------------------------------------------------------------------------
/** A piece under a name and a note of its own, everything else as it was. */
export function titled(p, name, note) {
    if (name === undefined && note === undefined)
        return p;
    if (name !== undefined && (typeof name !== "string" || !name.trim()))
        fail(`a name takes one line of words, such as "hello", not ${show(name)}`);
    const n = name?.trim() ?? p.meta.name;
    // A copy that still chains, everything else it carried kept.
    return chained({ ...p, meta: checkMeta({ ...p.meta, name: n, note: (note ?? n).slice(0, 72) }) });
}
// What every recipe takes for its name and note.
export const NAMING = ["name", "note"];
